/* ---- js/config.js ---- */
try {
/* ------------------------------------------------------------------
   TOYCOIN — site configuration (browser side)
   The live tracker's settings (mint, charity, RPCs, API key) live server-side
   in api/_lib/config.js / Vercel env vars — set TOY_MINT there too.
------------------------------------------------------------------- */
window.TOY_CONFIG = {
  // Contract address (mint) of $TOY on pump.fun. Leave "" until launch.
  // Keep it identical to TOY_MINT on the server.
  mint: "Fzx7qhj3JpYJSGWUMmZUhfM2p6evGSY3fsFRjgHFpump",

  // Links
  links: {
    pump: "https://pump.fun",  // becomes pump.fun/coin/<mint> automatically when mint is set
    donate: "https://www.donate.gg/charities/marine-toys-for-tots-foundation",
    charity: "https://www.toysfortots.org/",
    x: "https://x.com/toycoinpf_",
  },

  // "≈ toys" estimate and the journey animation (keep in sync with usdPerToy on the server)
  usdPerToy: 25,

  // Christmas countdown target (local time)
  christmas: "2026-12-25T00:00:00",
};

} catch (e) { console.error("[toycoin] js/config.js failed", e); }

/* ---- js/meter.js ---- */
try {
/* =====================================================================
   TOYCOIN — gift tracker (client)
   Standalone on purpose: no GSAP / Lenis dependency, so the numbers keep
   working even if the animation layer fails to load.
   All accounting happens server-side in /api/meter; this file only displays it.
===================================================================== */
(() => {
  "use strict";
  const API = "/api/meter";
  const REFRESH_MS = 60000;
  const TIMEOUT_MS = 12000;
  const $ = (s, c = document) => c.querySelector(s);
  const section = $("#tracker");
  if (!section) return;
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;

  const statusEl = $("#trkStatus");
  const setStatus = (text, cls) => {
    statusEl.className = "tracker__status" + (cls ? " is-" + cls : "");
    $(".tracker__status-text", statusEl).textContent = text;
  };

  /* ---------- formatting (BigInt in, strings out — no floats in the sums) ---------- */
  const usdE6 = (v) => {
    const n = Number(BigInt(v)) / 1e6;
    return "$" + n.toLocaleString("en-US", { minimumFractionDigits: n < 1000 ? 2 : 0, maximumFractionDigits: n < 1000 ? 2 : 0 });
  };
  const sol = (lam) => (Number(BigInt(lam)) / 1e9).toLocaleString("en-US", { minimumFractionDigits: 3, maximumFractionDigits: 3 });
  const ago = (iso) => {
    const s = Math.max(1, Math.floor((Date.now() - Date.parse(iso)) / 1000));
    if (s < 90) return s + "s ago"; if (s < 3600) return Math.floor(s / 60) + "m ago";
    if (s < 86400) return Math.floor(s / 3600) + "h ago"; return Math.floor(s / 86400) + "d ago";
  };
  const short = (a) => a.slice(0, 4) + "…" + a.slice(-4);
  const link = (href, text) => `<a href="${href}" target="_blank" rel="noopener">${text}</a>`;
  const acct = (a) => link("https://solscan.io/account/" + a, short(a));

  /* ---------- count-up (own rAF tween, eased) ---------- */
  const shown = {};
  let inView = false;
  const queued = {};
  function countTo(key, to, fmt) {
    const el = $(`[data-stat="${key}"]`);
    if (!inView || reduce) { shown[key] = to; queued[key] = [to, fmt]; el.textContent = fmt(to); return; }
    const from = shown[key] || 0, dur = from === 0 ? 2200 : 1200, t0 = performance.now();
    const step = (now) => {
      const k = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - k, 3);
      el.textContent = fmt(from + (to - from) * e);
      if (k < 1) requestAnimationFrame(step); else shown[key] = to;
    };
    requestAnimationFrame(step);
  }
  new IntersectionObserver(([e]) => {
    if (e.isIntersecting && !inView) {
      inView = true;
      for (const k in queued) { shown[k] = 0; countTo(k, queued[k][0], queued[k][1]); }
    }
  }, { threshold: 0.2 }).observe(section);

  const money = (v) => "$" + v.toLocaleString("en-US", { minimumFractionDigits: v < 1000 ? 2 : 0, maximumFractionDigits: v < 1000 ? 2 : 0 });
  const sol3 = (v) => v.toLocaleString("en-US", { minimumFractionDigits: 3, maximumFractionDigits: 3 });
  const whole = (v) => Math.round(v).toLocaleString("en-US");

  function setMeter(pct) {
    const fill = $("#meterFill"), bow = $("#meterBow");
    fill.style.transition = bow.style.transition = reduce ? "none" : "width 2s cubic-bezier(.2,.8,.2,1), left 2s cubic-bezier(.2,.8,.2,1)";
    fill.style.width = pct + "%"; bow.style.left = pct + "%";
  }

  /* ---------- render ---------- */
  let last = null;
  function render(d) {
    last = d;
    if (!d.configured) {
      setStatus("Waiting for the contract address — the tracker goes live the moment $TOY launches.", null);
      return;
    }
    const s = d.settled, p = d.pending;
    $('[data-meta="mint"]').innerHTML = link("https://solscan.io/token/" + d.mint, short(d.mint));

    // settled (the only thing counted as delivered)
    if (s) {
      countTo("delivered", Number(BigInt(s.netUsdE6)) / 1e6, money);
      countTo("toys", Number(s.toys), whole);
      $('[data-sub="delivered"]').textContent = s.receipts
        ? `${Number(s.receipts).toLocaleString("en-US")} settled donation${s.receipts === 1 ? "" : "s"} · last ${ago(s.lastSettlement.at)}`
        : "first settlement pending";
      $('[data-sub="toys"]').textContent = `at $${s.usdPerToy} per toy`;
      $('[data-meta="receipts"]').innerHTML = s.lastSettlement
        ? `${s.receipts} · ${link("https://solscan.io/tx/" + s.lastSettlement.tx, "last tx")}`
        : String(s.receipts);
      const gross = BigInt(s.grossUsdE6), fee = BigInt(s.feeUsdE6);
      const pct = gross > 0n ? Math.round(Number((fee * 10000n) / gross) / 100) : null;
      $('[data-meta="fees"]').textContent = usdE6(s.feeUsdE6) + (pct !== null ? ` (${pct}%)` : "");

      const list = $("#ledgerList");
      if (s.recent && s.recent.length) {
        list.innerHTML = "";
        s.recent.forEach((r) => {
          const li = document.createElement("li");
          const when = new Date(r.at).toLocaleString(undefined, { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
          li.innerHTML = `<span class="gift" aria-hidden="true">🎁</span>${link("https://solscan.io/tx/" + r.tx, when + " · " + short(r.tx))}<b>+${usdE6(r.netUsdE6)}</b>`;
          list.appendChild(li);
        });
      } else {
        list.innerHTML = '<li class="ledger__empty">No settlements yet — rewards are piling up under the tree.</li>';
      }
    } else {
      $('[data-sub="delivered"]').textContent = "settled data unavailable";
    }

    // on its way (shown, never counted)
    if (p) {
      const vaults = BigInt(p.creatorVaultLamports) + BigInt(p.ammVaultLamports);
      const donPending = p.donation ? BigInt(p.donation.pendingLamports) : 0n;
      const sent = p.donation ? BigInt(p.donation.totalDonatedLamports) : 0n;
      countTo("sent", Number(sent) / 1e9, sol3);
      countTo("pending", Number(vaults + donPending) / 1e9, sol3);
      $('[data-sub="sent"]').textContent = p.donation && p.donation.lastCrankAt ? `last hand-off ${ago(p.donation.lastCrankAt)}` : "on-chain total";
      if (p.minted === false) {
        $('[data-sub="sent"]').textContent = "starts at mint";
        $('[data-sub="pending"]').textContent = "starts with the first trade";
      }
      $('[data-meta="sharing"]').innerHTML = acct(p.accounts.sharing) + (p.locked ? " · locked" : "");
      $('[data-meta="donation"]').innerHTML = p.donation ? acct(p.donation.address) : "—";
      $('[data-meta="vaults"]').innerHTML = acct(p.accounts.creatorVault) + " · " + acct(p.accounts.pumpswapVault);

      // ribbon: SOL behind settled receipts vs. every SOL of creator rewards routed or waiting
      const settledSol = s ? BigInt(s.sourceLamports) : 0n;
      const all = sent + donPending + vaults;
      const pct = all > 0n ? Math.min(100, Number((settledSol * 10000n) / all) / 100) : 0;
      countTo("pct", pct, (v) => v.toFixed(1) + "%");
      setMeter(pct);

      const lock = $("#meterLock");
      if (p.locked && p.shareBps) {
        lock.hidden = false;
        lock.textContent = `Locked on-chain: ${Math.round(p.shareBps / 100)}% of creator rewards → donate.gg → Toys for Tots. The split can never be changed.`;
      }
    } else {
      $('[data-sub="pending"]').textContent = "vault balances unavailable";
    }

    const stale = !s || s.stale;
    if (!s) setStatus("Settled data unavailable right now — retrying.", "error");
    else if (stale) setStatus("Showing the last confirmed reading (cached).", "idle");
    else setStatus("Live — settled donations from donate.gg, balances from Solana.", "live");
    updateStamp();
  }

  function updateStamp() {
    if (!last || !last.configured) return;
    const s = last.settled;
    const parts = [];
    if (s && s.fetchedAt) parts.push("settled " + ago(s.fetchedAt));
    if (last.pending && last.pending.fetchedAt) parts.push("chain " + ago(last.pending.fetchedAt));
    $('[data-meta="updated"]').textContent = parts.join(" · ") || "—";
  }
  setInterval(updateStamp, 15000);

  /* ---------- polling ----------
     Every /api/meter call is a CDN request on the hosting bill, so the tracker only asks while its
     section is on (or near) the screen and the tab is visible — visitors who never scroll down to
     it cost nothing, and an open-but-idle tab stops polling. */
  let busy = false, near = false, lastFetch = 0;
  async function load(force) {
    if (busy || document.hidden || !near) return;
    if (!force && Date.now() - lastFetch < REFRESH_MS - 1000) return;
    busy = true;
    lastFetch = Date.now();
    const ctrl = new AbortController(), timer = setTimeout(() => ctrl.abort(), TIMEOUT_MS);
    try {
      const r = await fetch(API, { signal: ctrl.signal, headers: { Accept: "application/json" } });
      if (!r.ok) throw new Error("HTTP " + r.status);
      render(await r.json());
    } catch (e) {
      if (last && last.configured) setStatus("Showing the last confirmed reading (cached).", "idle");
      else if (!last) setStatus("Tracker unavailable right now — retrying.", "error");
    } finally { clearTimeout(timer); busy = false; }
  }
  new IntersectionObserver(([e]) => {
    near = e.isIntersecting;
    if (near) load();                       // first view, or back after REFRESH_MS
  }, { rootMargin: "600px 0px" }).observe(section);
  setInterval(() => load(), REFRESH_MS);
  document.addEventListener("visibilitychange", () => { if (!document.hidden) load(); });
  addEventListener("online", () => load(true));
})();

} catch (e) { console.error("[toycoin] js/meter.js failed", e); }

/* ---- js/main.js ---- */
try {
/* =====================================================================
   TOYCOIN — interactions, motion & tracker UI
===================================================================== */
(() => {
  const CFG = window.TOY_CONFIG || {};
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const hasGsap = !!window.gsap;
  if (hasGsap && window.ScrollTrigger) gsap.registerPlugin(ScrollTrigger);

  /* ---------- links + CA ---------- */
  const links = Object.assign({}, CFG.links);
  if (CFG.mint) links.pump = "https://pump.fun/coin/" + CFG.mint;
  $$("[data-link]").forEach((a) => {
    const url = links[a.dataset.link];
    if (url) a.href = url;
  });
  if (CFG.mint) $$("[data-ca]").forEach((el) => (el.textContent = CFG.mint));

  const toast = (msg) => {
    const t = $("#toast");
    t.textContent = msg;
    t.classList.add("is-on");
    clearTimeout(toast._t);
    toast._t = setTimeout(() => t.classList.remove("is-on"), 2200);
  };
  $("#caPill").addEventListener("click", async () => {
    if (!CFG.mint) return toast("🎁 The contract address drops at launch.");
    try { await navigator.clipboard.writeText(CFG.mint); toast("Contract address copied ✓"); }
    catch { toast(CFG.mint); }
  });

  /* ---------- nav ---------- */
  const nav = $("#nav"), burger = $(".nav__burger"), drawer = $("#drawer");
  let lastY = 0;
  const onScroll = (y) => {
    nav.classList.toggle("is-solid", y > window.innerHeight * 0.6);
    nav.classList.toggle("is-hidden", y > 600 && y > lastY && drawer.hidden);
    lastY = y;
  };
  burger.addEventListener("click", () => {
    const open = drawer.hidden;
    drawer.hidden = !open;
    burger.setAttribute("aria-expanded", String(open));
    nav.classList.add("is-solid");
  });
  drawer.addEventListener("click", (e) => {
    if (e.target.tagName === "A") { drawer.hidden = true; burger.setAttribute("aria-expanded", "false"); }
  });

  /* ---------- smooth scroll ---------- */
  let lenis = null;
  if (window.Lenis && !reduce) {
    lenis = new Lenis({ lerp: 0.1, smoothWheel: true });
    lenis.on("scroll", (e) => { onScroll(e.scroll); window.__scrollVelocity = e.velocity; if (window.ScrollTrigger) ScrollTrigger.update(); });
    if (hasGsap) { gsap.ticker.add((t) => lenis.raf(t * 1000)); gsap.ticker.lagSmoothing(0); }
    else { const raf = (t) => { lenis.raf(t); requestAnimationFrame(raf); }; requestAnimationFrame(raf); }
  } else {
    addEventListener("scroll", () => onScroll(scrollY), { passive: true });
  }
  $$('a[href^="#"]').forEach((a) => a.addEventListener("click", (e) => {
    const id = a.getAttribute("href");
    if (id.length < 2) return;
    const el = $(id);
    if (!el) return;
    e.preventDefault();
    lenis ? lenis.scrollTo(el, { offset: id === "#top" ? 0 : -20, duration: 1.4 }) : el.scrollIntoView({ behavior: "smooth" });
  }));

  /* ---------- split headings into words ---------- */
  $$(".split").forEach((el) => {
    const walk = (node) => {
      [...node.childNodes].forEach((n) => {
        if (n.nodeType === 3) {
          const frag = document.createDocumentFragment();
          n.textContent.split(/(\s+)/).forEach((part) => {
            if (!part) return;
            if (/^\s+$/.test(part)) { frag.appendChild(document.createTextNode(" ")); return; }
            const w = document.createElement("span"); w.className = "w";
            const i = document.createElement("span"); i.textContent = part;
            w.appendChild(i); frag.appendChild(w);
          });
          n.replaceWith(frag);
        } else if (n.nodeType === 1 && n.tagName !== "BR") walk(n);
      });
    };
    walk(el);
  });

  /* ---------- snow ---------- */
  $$("canvas.snow").forEach((cv) => {
    const ctx = cv.getContext("2d");
    const density = parseFloat(cv.dataset.density || "1");
    let w, h, flakes = [], visible = true, dpr = Math.min(devicePixelRatio || 1, 2);
    const resize = () => {
      w = cv.clientWidth; h = cv.clientHeight;
      cv.width = w * dpr; cv.height = h * dpr; ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const n = Math.round((w * h) / 9000 * density);
      flakes = Array.from({ length: n }, () => ({
        x: Math.random() * w, y: Math.random() * h,
        r: Math.random() * 2.4 + 0.6, s: Math.random() * 0.6 + 0.25,
        d: Math.random() * Math.PI * 2, o: Math.random() * 0.6 + 0.25,
      }));
    };
    resize(); addEventListener("resize", resize);
    new IntersectionObserver(([e]) => (visible = e.isIntersecting)).observe(cv);
    let mx = 0;
    addEventListener("pointermove", (e) => (mx = (e.clientX / innerWidth - 0.5) * 0.8), { passive: true });
    const tick = (t) => {
      if (visible) {
        ctx.clearRect(0, 0, w, h);
        for (const f of flakes) {
          f.y += f.s * (reduce ? 0.3 : 1);
          f.x += Math.sin(t / 1600 + f.d) * 0.35 + mx * f.r * 0.4;
          if (f.y > h + 5) { f.y = -5; f.x = Math.random() * w; }
          if (f.x > w + 5) f.x = -5; if (f.x < -5) f.x = w + 5;
          ctx.globalAlpha = f.o;
          ctx.fillStyle = "#FFF4E3";
          ctx.beginPath(); ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2); ctx.fill();
        }
      }
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  });

  /* ---------- marquee (scroll-velocity reactive) ---------- */
  const track = $(".marquee__track");
  if (track) {
    let x = 0, speed = 0.6, dir = -1;
    const loop = () => {
      const v = window.__scrollVelocity || 0;
      if (Math.abs(v) > 0.2) dir = v > 0 ? -1 : 1;
      x += dir * (speed + Math.min(Math.abs(v) * 0.35, 14));
      const half = track.scrollWidth / 2;
      if (x <= -half) x += half; if (x > 0) x -= half;
      track.style.transform = `translate3d(${x}px,0,0)`;
      window.__scrollVelocity = (window.__scrollVelocity || 0) * 0.9;
      requestAnimationFrame(loop);
    };
    if (!reduce) requestAnimationFrame(loop);
  }

  /* ---------- magnetic buttons ---------- */
  if (!reduce && matchMedia("(pointer: fine)").matches) {
    $$(".magnetic").forEach((b) => {
      b.addEventListener("pointermove", (e) => {
        const r = b.getBoundingClientRect();
        const dx = e.clientX - (r.left + r.width / 2), dy = e.clientY - (r.top + r.height / 2);
        b.style.transform = `translate(${dx * 0.18}px, ${dy * 0.28}px)`;
      });
      b.addEventListener("pointerleave", () => { b.style.transition = "transform .5s cubic-bezier(.2,.8,.2,1)"; b.style.transform = ""; setTimeout(() => (b.style.transition = ""), 500); });
    });
  }

  /* ---------- GSAP choreography ---------- */
  if (hasGsap && !reduce) {
    // Intro
    const intro = gsap.timeline({ defaults: { ease: "expo.out" } });
    intro
      // explicit end values + clearProps: a .from() here would bake whatever transform the nav
      // has at load (e.g. "hidden" after a mid-page reload) into a permanent inline style
      .fromTo(".nav", { y: -30, opacity: 0 }, { y: 0, opacity: 1, duration: 1, clearProps: "all" }, 0.1)
      .from(".eyebrow", { y: 20, opacity: 0, duration: 1 }, 0.2)
      .from(".hero__title .w > span", { yPercent: 110, rotate: 4, duration: 1.3, stagger: 0.06 }, 0.25)
      .from(".hero__lede, .hero__ctas, .ca", { y: 26, opacity: 0, duration: 1.1, stagger: 0.08 }, 0.6)
      .from("#coinWrap", { scale: 0.6, opacity: 0, duration: 1.8, ease: "elastic.out(1, .6)" }, 0.35)
      .from(".block", { y: -340, opacity: 0, duration: 1.1, stagger: 0.12, ease: "bounce.out" }, 0.8)
      .from(".hero__scroll", { opacity: 0, duration: 1 }, 1.4);

    // Hero parallax out
    gsap.to(".hero__copy", { yPercent: -18, opacity: 0.2, ease: "none", scrollTrigger: { trigger: ".hero", start: "top top", end: "bottom top", scrub: true } });
    gsap.to(".blocks", { y: 120, rotate: 8, ease: "none", scrollTrigger: { trigger: ".hero", start: "top top", end: "bottom top", scrub: true } });

    // Section headings
    $$(".split").forEach((el) => {
      if (el.closest(".hero")) return;
      gsap.from(el.querySelectorAll(".w > span"), {
        yPercent: 115, rotate: 3, duration: 1.2, ease: "expo.out", stagger: 0.05,
        scrollTrigger: { trigger: el, start: "top 85%" },
      });
    });
    $$(".kicker, .section-sub").forEach((el) => gsap.from(el, { y: 20, opacity: 0, duration: 1, ease: "expo.out", scrollTrigger: { trigger: el, start: "top 90%" } }));

    // Tracker cards
    gsap.from(".stat, .ribbon-meter, .ledger__col, .tracker__status", {
      y: 60, opacity: 0, duration: 1.1, ease: "expo.out", stagger: 0.08,
      scrollTrigger: { trigger: ".stats", start: "top 85%" },
    });

    // How-it-works ribbon + steps
    const rib = $("#howRibbon");
    if (rib) {
      rib.setAttribute("pathLength", "1");
      gsap.to(rib, { strokeDashoffset: 0, ease: "none", scrollTrigger: { trigger: ".how__track", start: "top 75%", end: "bottom 60%", scrub: 1 } });
    }
    gsap.from(".step", { y: 80, opacity: 0, rotate: (i) => (i % 2 ? 3 : -3), duration: 1.2, ease: "expo.out", stagger: 0.12, scrollTrigger: { trigger: ".steps", start: "top 80%" } });

    // Charity toy box — float in + parallax
    $$(".toy").forEach((t, i) => {
      gsap.from(t, { scale: 0, rotate: (i % 2 ? 30 : -30), opacity: 0, duration: 1.3, ease: "back.out(1.6)", delay: i * 0.07, scrollTrigger: { trigger: ".toybox", start: "top 80%" } });
      gsap.to(t, { y: (i % 3 - 1) * 70, rotate: (i % 2 ? 8 : -8), ease: "none", scrollTrigger: { trigger: ".charity", start: "top bottom", end: "bottom top", scrub: true } });
      gsap.to(t, { y: "+=12", duration: 2.4 + i * 0.3, repeat: -1, yoyo: true, ease: "sine.inOut", delay: 1.5 });
    });

    // Gift tags swing in on their strings
    gsap.from(".tag", { rotateX: -80, rotate: (i) => (i % 2 ? 12 : -12), opacity: 0, transformOrigin: "50% -30px", duration: 1.6, ease: "elastic.out(1, .45)", stagger: 0.09, scrollTrigger: { trigger: ".tags", start: "top 80%" } });

    // Advent doors
    gsap.from(".door", { rotateY: -90, transformOrigin: "left center", opacity: 0, duration: 1.2, ease: "expo.out", stagger: 0.1, scrollTrigger: { trigger: ".doors", start: "top 85%" } });

    // FAQ + footer
    gsap.from(".faq__list details", { y: 30, opacity: 0, duration: 0.9, ease: "expo.out", stagger: 0.07, scrollTrigger: { trigger: ".faq__list", start: "top 85%" } });
    gsap.from(".footer__word", { yPercent: 60, opacity: 0, duration: 1.4, ease: "expo.out", scrollTrigger: { trigger: ".footer", start: "top 90%" } });
  } else {
    $("#howRibbon") && $("#howRibbon").setAttribute("pathLength", "1");
    $("#howRibbon") && ($("#howRibbon").style.strokeDashoffset = 0);
  }

  /* ---------- countdown ---------- */
  const target = new Date(CFG.christmas || "2026-12-25T00:00:00").getTime();
  const cd = { d: $('[data-cd="d"]'), h: $('[data-cd="h"]'), m: $('[data-cd="m"]'), s: $('[data-cd="s"]') };
  const pad = (n) => String(n).padStart(2, "0");
  const tickCd = () => {
    let diff = Math.max(0, target - Date.now());
    const d = Math.floor(diff / 864e5); diff -= d * 864e5;
    const h = Math.floor(diff / 36e5); diff -= h * 36e5;
    const m = Math.floor(diff / 6e4); diff -= m * 6e4;
    const s = Math.floor(diff / 1e3);
    const set = (el, v) => {
      if (el.textContent === v) return;
      el.textContent = v;
      if (hasGsap && !reduce) gsap.fromTo(el, { yPercent: -30, opacity: 0.2 }, { yPercent: 0, opacity: 1, duration: 0.45, ease: "back.out(2)" });
    };
    set(cd.d, pad(d)); set(cd.h, pad(h)); set(cd.m, pad(m)); set(cd.s, pad(s));
    if (target <= Date.now()) $(".countdown .kicker").textContent = "Merry Christmas — it’s here";
  };
  tickCd(); setInterval(tickCd, 1000);

})();

} catch (e) { console.error("[toycoin] js/main.js failed", e); }

