      const p = document.createElementNS(NS, "path");
      p.setAttribute("d", "M0 -8 L2.2 -2.2 8 0 2.2 2.2 0 8 -2.2 2.2 -8 0 -2.2 -2.2Z");
      p.setAttribute("fill", i % 2 ? "#F2C66B" : "#FFF4E3");
